<script setup>
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {api} from './api'
const emit=defineEmits(['busy'])
let timer,stopped=false,polling=false
const props=defineProps({language:String})
const tr=(ru,uz,en)=>({ru,uz,en}[props.language]||ru)
const state=ref(null),token=ref(''),pairing=ref(null),phone=ref(null),busy=ref(false),error=ref(''),manual=ref(false),network=ref(null),selected=ref('eth0'),now=ref(Date.now())
const interfaces=computed(()=>(network.value?.interfaces||[]).filter(i=>i.connected&&i.address))
const seconds=computed(()=>Math.max(0,Math.ceil((Date.parse(phone.value?.expires_at||'')-now.value)/1000)))
const request=(action,payload)=>api('/api/commissioning/telegram/'+action,payload?{method:'POST',body:JSON.stringify(payload)}:{})
async function load(){state.value=await request('status');if(state.value.owner_paired)pairing.value=null;if(state.value.configured){phone.value=null;token.value='';manual.value=false}}
async function loadNetwork(){network.value=await api('/api/commissioning/network/status');selected.value=network.value.temporary_wifi&&interfaces.value.some(i=>i.interface==='wlan0')?'wlan0':interfaces.value.find(i=>i.interface==='eth0')?.interface||interfaces.value[0]?.interface||''}
async function run(fn){if(busy.value)return;busy.value=true;emit('busy',true);error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false;emit('busy',false)}}
async function configure(){try{state.value=await request('configure-auto',{token:token.value});pairing.value=null;await load()}finally{token.value=''}}
async function createPhone(){phone.value=await request('mobile/session',{interface:selected.value,language:props.language||'ru'});manual.value=false;token.value=''}
onMounted(()=>{run(async()=>{await load();if(state.value.install_manage_allowed!==false&&!state.value.configured)await loadNetwork()});timer=setInterval(async()=>{now.value=Date.now();if((phone.value||pairing.value)&&!busy.value&&!polling&&!stopped&&!document.hidden){polling=true;try{await load()}catch(e){if(!stopped)error.value=e.message}finally{polling=false}}},2000)})
onUnmounted(()=>{stopped=true;clearInterval(timer);token.value='';emit('busy',false)})
</script>
<template><section class="card content"><h2>Telegram</h2><p v-if="state?.install_manage_allowed!==false">{{tr('Подключите бота с телефона, затем привяжите владельца. Этот шаг можно пропустить и выполнить позже в Owner.','Botni telefondan ulang, keyin egasini biriktiring. Bu bosqichni o‘tkazib, keyin Owner orqali sozlash mumkin.','Connect the bot from your phone, then pair the owner. You can skip this step and set it up later in Owner.')}}</p><p v-if="error" class="message error" role="alert">{{error}}</p><template v-if="state"><p v-if="state.install_manage_allowed!==false" role="status">{{state.configured?'@'+state.bot_username:tr('Бот не подключён','Bot ulanmagan','Bot not connected')}} · {{state.owner_paired?tr('Владелец привязан','Egasi ulangan','Owner paired'):tr('Владелец не привязан','Egasi ulanmagan','Owner not paired')}}</p><p v-if="state.install_manage_allowed===false" class="muted">{{tr('Telegram настраивается на главном посте.','Telegram asosiy postda sozlanadi.','Configure Telegram on the primary station.')}} {{state.primary_post}}</p>
<template v-else>
<section v-if="!state.configured" class="phone-setup"><h3>{{tr('1. Подключить бота с телефона','1. Botni telefondan ulash','1. Connect the bot from your phone')}}</h3><p>{{tr('Скопируйте токен из BotFather на телефоне и вставьте на странице, открытой по QR.','Telefonda BotFather tokenini nusxalab, QR orqali ochilgan sahifaga joylashtiring.','Copy the token from BotFather on your phone and paste it on the page opened by the QR code.')}}</p><label>{{tr('Как телефон подключён к посту','Telefon postga qanday ulangan','Phone connection to the station')}}<select v-model="selected" :disabled="busy" @change="phone=null" :aria-label="tr('Сеть телефона','Telefon tarmog‘i','Phone network')"><option v-for="i in interfaces" :key="i.interface" :value="i.interface">{{i.interface==='eth0'?tr('Через роутер мойки','Yuvish routeri orqali','Through the site router'):tr('Через Wi-Fi / точку доступа телефона','Wi-Fi / telefon kirish nuqtasi orqali','Through Wi-Fi / phone hotspot')}} · {{i.address}}</option></select></label><div class="actions"><button class="primary" :disabled="busy||!selected" @click="run(createPhone)">{{phone?tr('Создать новый QR','Yangi QR yaratish','Create new QR'):tr('Настроить с телефона','Telefondan sozlash','Set up with a phone')}}</button><button class="quiet" :disabled="busy" @click="run(loadNetwork)">{{tr('Обновить подключения','Ulanishlarni yangilash','Refresh connections')}}</button></div>
<div v-if="phone" class="phone-qr"><img v-if="seconds>0" :src="phone.qr_data_url" :alt="tr('QR настройки Telegram с телефона','Telefondan Telegramni sozlash QR kodi','Phone Telegram setup QR')" width="300" height="300"/><div><strong>{{seconds>0?tr('Отсканируйте камерой телефона','Telefon kamerasi bilan skanerlang','Scan with your phone camera'):tr('Ссылка истекла — создайте новый QR','Havola eskirdi — yangi QR yarating','Link expired — create a new QR')}}</strong><p>{{tr('Одноразовая ссылка · 10 минут','Bir martalik havola · 10 daqiqa','Single-use link · 10 minutes')}}</p><p>{{tr('Телефон должен видеть указанный адрес поста. При подключении к роутеру используйте его Wi-Fi. Если телефон раздаёт интернет посту, выберите Wi-Fi выше.','Telefon ko‘rsatilgan post manziliga kira olishi kerak. Router uchun uning Wi-Fi tarmog‘idan foydalaning. Telefon postga internet tarqatsa, yuqorida Wi-Fi ni tanlang.','Your phone must reach the station address. Use the site router Wi-Fi, or choose Wi-Fi above when your phone provides the hotspot.')}}</p><a v-if="seconds>0" :href="phone.mobile_url" target="_blank" rel="noopener noreferrer">{{tr('Открыть страницу настройки','Sozlash sahifasini ochish','Open setup page')}}</a><p class="muted">{{tr('После подключения статус здесь обновится автоматически.','Ulangach bu yerda holat avtomatik yangilanadi.','This screen updates automatically after connection.')}}</p></div></div>
<button class="quiet alternative" :disabled="busy" @click="manual=!manual;token=''">{{manual?tr('Скрыть ручной ввод','Qo‘lda kiritishni yashirish','Hide manual entry'):tr('Другой способ: ввести токен на экране','Boshqa usul: tokenni ekranda kiritish','Other method: enter the token on screen')}}</button><form v-if="manual" @submit.prevent="run(configure)"><label>BotFather token<input v-model="token" type="password" required autocomplete="off" maxlength="256"/></label><button class="primary" :disabled="busy||!token">{{tr('Проверить и подключить','Tekshirish va ulash','Verify & connect')}}</button></form></section>
<section v-if="state.configured&&!state.owner_paired" class="owner-setup"><h3>{{tr('2. Привязать владельца','2. Egasini ulash','2. Pair the owner')}}</h3><p>{{tr('Бот подключён. Теперь создайте отдельный QR для владельца Telegram.','Bot ulandi. Endi Telegram egasi uchun alohida QR yarating.','Bot connected. Now create a separate QR for the Telegram owner.')}}</p><button class="primary" :disabled="busy||!state.enabled" @click="run(async()=>{pairing=await request('pairing',{reset_owner:false})})">{{tr('Привязать владельца','Egasini ulash','Pair owner')}}</button></section>
<div v-if="pairing" class="phone-qr"><img :src="pairing.qr_data_url" alt="Telegram QR" width="300" height="300"/><p>{{tr('Отсканируйте QR и нажмите Start в Telegram.','QRni skanerlang va Telegramda Start bosing.','Scan the QR and press Start in Telegram.')}}</p></div><div class="actions"><button type="button" class="quiet" :disabled="busy||!state.identity_configured" @click="run(async()=>{await request('discover',{});await load()})">{{tr('Найти посты автоматически','Postlarni avtomatik topish','Discover stations')}}</button><button type="button" class="quiet" :disabled="busy" @click="run(load)">{{tr('Обновить статус','Holatni yangilash','Refresh status')}}</button></div></template><p v-for="post in state.posts||[]" :key="post.id">{{post.name}} · {{post.host}}</p></template></section></template>
<style scoped>label{display:grid;gap:12px}.actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:24px}p{line-height:1.6}.phone-setup,.owner-setup{padding-top:16px;border-top:1px solid var(--border);margin-top:24px}.phone-qr{display:grid;grid-template-columns:minmax(220px,300px) 1fr;align-items:center;gap:24px;margin:24px 0}.phone-qr img{display:block;background:white;padding:10px;border-radius:12px;width:100%;height:auto;max-width:300px}.phone-qr a{overflow-wrap:anywhere;color:var(--accent,#1764d8)}.alternative{margin:24px 0}form{display:grid;gap:20px}@media(max-width:650px){.phone-qr{grid-template-columns:1fr}.phone-qr img{justify-self:center}}</style>
